    #[test]
    fn a_kept_identity_lasts_until_a_commit_changes_what_it_holds() {
        let mut db = Database::initialize(Connection::open_in_memory().unwrap()).unwrap();
        let shared = db.shared();
        db.conn
            .execute_batch(
                "INSERT INTO bots(name,id,status,provider,family,model)
                 VALUES ('Bob',7,'idle','openai','responses','m');
                 INSERT INTO texts(id,digest,text) VALUES
                    (1,'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855','');
                 INSERT INTO bot_instructions(id,instructions) VALUES (7,1)",
            )
            .unwrap();
        let read = |db: &Database| Arc::new(Identity::from(db.inspect_id(7).unwrap()));
        let generation = shared.identity(7).unwrap_err();
        shared.know(generation, read(&db));
        let kept = shared.identity(7).unwrap();
        assert!(!kept.sandboxed());
        let commit = |db: &mut Database, sql: &str| {
            db.begin_group().unwrap();
            db.conn.execute_batch(sql).unwrap();
            db.commit_group().unwrap();
        };
        // A turn's bookkeeping changes nothing a request is held to.
        commit(
            &mut db,
            "UPDATE bots SET tokens_used=5, status='running' WHERE id=7",
        );
        assert!(Arc::ptr_eq(&kept, &shared.identity(7).unwrap()));
        // A read taken before a change commits is not kept after it.
        db.begin_group().unwrap();
        db.conn
            .execute_batch(r#"UPDATE bots SET settings='{"sandbox":"read-only"}' WHERE id=7"#)
            .unwrap();
        assert!(
            Arc::ptr_eq(&kept, &shared.identity(7).unwrap()),
            "until it commits"
        );
        let before = read(&db);
        db.commit_group().unwrap();
        let generation = shared.identity(7).unwrap_err();
        shared.know(generation - 1, before);
        assert!(shared.identity(7).is_err());
        shared.know(generation, read(&db));
        assert!(shared.identity(7).unwrap().sandboxed());
        // An abandoned group's change is read again too, and so is a bot
        // gone.
        db.begin_group().unwrap();
        db.conn
            .execute_batch("UPDATE bots SET workspace='/elsewhere' WHERE id=7")
            .unwrap();
        db.abandon_group().unwrap();
        let generation = shared.identity(7).unwrap_err();
        shared.know(generation, read(&db));
        commit(
            &mut db,
            "DELETE FROM bot_instructions WHERE id=7; DELETE FROM bots WHERE id=7",
        );
        assert!(shared.identity(7).is_err());
        assert_eq!(db.inspect_id(7).unwrap_err().code, "bot_not_found");
    }

    #[test]
    fn a_cached_statement_is_not_planned_again_when_reused() {
        let dir = std::env::temp_dir().join(format!("agent-plans-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("state.sqlite");
        let mut writer = Database::initialize(Connection::open(&path).unwrap()).unwrap();
        let mut reader =
            Database::reader(Connection::open(&path).unwrap(), writer.shared()).unwrap();
        for db in [&mut writer, &mut reader] {
            let conn = db.connection();
            // A join with a bound value, as `history_items` reads an item.
            let sql = "SELECT n.id FROM nodes n LEFT JOIN declined d ON d.node=n.id WHERE n.id=?1";
            for value in [1, 2, 3] {
                let mut statement = conn.prepare_cached(sql).unwrap();
                statement.query([value]).unwrap().next().unwrap();
            }
            let statement = conn.prepare_cached(sql).unwrap();
            assert_eq!(
                statement.get_status(rusqlite::StatementStatus::RePrepare),
                0
            );
        }
        drop((reader, writer));
        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_history_read_leaves_out_the_state_a_provider_replays() {
        let conn = Connection::open_in_memory().unwrap();
        let read = |item: &str| -> Value {
            let text: String = conn
                .query_row(
                    &format!(
                        "SELECT CAST({READING_ITEM} AS TEXT) FROM (SELECT CAST(?1 AS BLOB) AS item)"
                    ),
                    [item],
                    |r| r.get(0),
                )
                .unwrap();
            assert!(!text.contains('\n'), "{text}");
            serde_json::from_str(&text).unwrap()
        };
        let claude = json!({"role": "assistant", "content": [
            {"type": "thinking", "thinking": "plan", "signature": "sig".repeat(100)},
            {"type": "redacted_thinking", "data": "opaque"},
            {"type": "server_tool_use", "id": "s", "name": "web_search", "input": {"query": "q"}},
            {"type": "web_search_tool_result", "tool_use_id": "s", "content": [
                {"type": "web_search_result", "url": "https://example.test", "title": "T",
                 "encrypted_content": "opaque"}]},
            {"type": "text", "text": "a \"signature\" in words stays"}]});
        assert_eq!(
            read(&serde_json::to_string_pretty(&claude).unwrap()),
            json!({"role": "assistant", "content": [
                {"type": "thinking", "thinking": "plan"},
                {"type": "redacted_thinking"},
                {"type": "server_tool_use", "id": "s", "name": "web_search", "input": {"query": "q"}},
                {"type": "web_search_tool_result", "tool_use_id": "s", "content": [
                    {"type": "web_search_result", "url": "https://example.test", "title": "T"}]},
                {"type": "text", "text": "a \"signature\" in words stays"}]})
        );
        let reasoning = json!({"type": "reasoning", "summary": [], "encrypted_content": "x"});
        assert_eq!(
            read(&reasoning.to_string()),
            json!({"type": "reasoning", "summary": []})
        );
        // Anything else reads as it is stored.
        let user = json!({"role": "user", "content": [{"type": "text", "text": "\"signature\""}]});
        assert_eq!(read(&user.to_string()), user);
    }

    #[test]
    fn a_cut_patch_still_names_every_file_it_changes() {
        let input = format!(
            "*** Begin Patch\n*** Add File: notes.txt\n+{}\n*** Add File: run.sh\n+ls\n*** End Patch",
            "x".repeat(3000)
        );
        let call = ToolCall {
            name: "apply_patch".into(),
            call_id: "c".into(),
            arguments: json!({"input":input}).to_string(),
            custom: true,
            links: Default::default(),
        };
        let data = started(&call);
        assert_eq!(data["arguments_truncated"], true);
        assert_eq!(data["paths"], json!(["notes.txt", "run.sh"]));
        let short = ToolCall {
            arguments: json!({"input":"*** Begin Patch\n*** Add File: a\n+b\n*** End Patch"})
                .to_string(),
            ..call
        };
        assert!(started(&short).get("paths").is_none());
        // Past what an event carries, the paths named stop and say so.
        let mut input = "*** Begin Patch\n".to_owned();
        for n in 0..3000 {
            input.push_str(&format!("*** Delete File: {}{n}\n", "d/".repeat(100)));
        }
        input.push_str("*** End Patch");
        let many = ToolCall {
            arguments: json!({"input":input}).to_string(),
            ..short
        };
        let data = started(&many);
        assert_eq!(data["paths_cut"], true);
        assert!(data.to_string().len() < 80 * 1024);
    }

